import * as React from 'react';
import { cn } from '@/lib/utils';

export type FieldsetProps = React.FieldsetHTMLAttributes<HTMLFieldSetElement> & {
  /** Legend rendered as the group's accessible name. */
  legend?: string;
  /** Muted supporting line rendered under the legend. */
  description?: string;
  /** Error line rendered under the controls; announced via role=alert. */
  error?: string;
};

/**
 * Groups related form controls in a native <fieldset> with a legend,
 * optional description, and an error slot. Styling is token-based
 * (borderless by default — the native border reads as chrome, not content).
 */
const Fieldset = React.forwardRef<HTMLFieldSetElement, FieldsetProps>(
  ({ legend, description, error, className, children, ...props }, ref) => (
    <fieldset
      ref={ref}
      className={cn('m-0 flex min-w-0 flex-col gap-1.5 border-0 p-0', className)}
      {...props}
    >
      {legend && <legend className="p-0 text-sm font-medium leading-none">{legend}</legend>}
      {description && <p className="text-xs text-muted-foreground">{description}</p>}
      {children}
      {error && (
        <p role="alert" className="text-xs text-destructive">
          {error}
        </p>
      )}
    </fieldset>
  )
);
Fieldset.displayName = 'Fieldset';

export { Fieldset };

{
  "id": "fieldset",
  "name": "Fieldset",
  "tier": "atom",
  "description": "Groups related form controls in a native fieldset with a legend, optional description, and an error slot.",
  "designIntent": "Radio groups, checkbox groups, and multi-control sections need an accessible group name. Fieldset provides the native <fieldset>/<legend> semantics with token-based styling (borderless by default) plus description and error slots so related controls read as one unit.",
  "props": [
    {
      "name": "legend",
      "type": "string",
      "required": false,
      "description": "Legend rendered as the group's accessible name.",
      "examples": [
        "Choose a plan",
        "Notification preferences"
      ]
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Muted supporting line rendered under the legend.",
      "examples": [
        "Applies to every project in this workspace"
      ]
    },
    {
      "name": "error",
      "type": "string",
      "required": false,
      "description": "Error line rendered under the controls; announced via role=alert.",
      "examples": [
        "Select at least one option"
      ]
    }
  ],
  "examples": [
    {
      "title": "Grouped radio-style options",
      "code": "<Fieldset legend=\"Export format\" description=\"Applied to every selected row\">\n  <Checkbox id=\"csv\" /><Label htmlFor=\"csv\">CSV</Label>\n  <Checkbox id=\"json\" /><Label htmlFor=\"json\">JSON</Label>\n</Fieldset>",
      "description": "Legend names the group; description adds context."
    },
    {
      "title": "With a group-level error",
      "code": "<Fieldset legend=\"Visibility\" error=\"Choose who can see this project\">\n  <RadioGroupItem value=\"private\" label=\"Private\" />\n  <RadioGroupItem value=\"team\" label=\"Team\" />\n</Fieldset>",
      "description": "Errors that belong to the whole group live on the fieldset, not each control."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use a fieldset for layout grouping",
      "explanation": "Fieldset is for FORM controls that share one accessible name. For purely visual grouping use Card or a plain div — screen readers announce every fieldset as a landmark-ish group and excess ones add noise.",
      "example": "// Avoid: fieldset around non-form content\n<fieldset><legend>Footer</legend><p>…</p></fieldset>\n\n// Prefer: Card or div for layout\n<Card>…</Card>"
    },
    {
      "title": "Don't skip the legend",
      "explanation": "A fieldset without legend (or without aria-label) leaves the group unnamed — controls inside lose their grouping context for screen reader users.",
      "example": "<Fieldset legend=\"Billing interval\">…</Fieldset>"
    }
  ],
  "accessibility": [
    {
      "feature": "Native group semantics",
      "implementation": "Renders <fieldset> with <legend>; the legend is the group's accessible name announced before each control",
      "userRequirements": "Always pass a legend (or an equivalent aria-label)"
    },
    {
      "feature": "Group-level errors",
      "implementation": "The error slot renders with role=alert so it is announced when it appears",
      "userRequirements": "Keep the message actionable ('Choose at least one option')"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Legends",
      "guidelines": [
        "Use sentence case",
        "Phrase as the question or choice name",
        "Keep under 60 characters"
      ],
      "goodExamples": [
        "Choose a plan",
        "Billing interval"
      ],
      "badExamples": [
        "Options",
        "Click here"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "RadioGroup / Checkbox",
      "relationship": "Wrap mutually exclusive or multi-select controls so their group name is announced",
      "example": "<Fieldset legend=\"Plan\"><RadioGroup name=\"plan\">…</RadioGroup></Fieldset>"
    },
    {
      "component": "FormField",
      "relationship": "For a single labeled control prefer FormField; Fieldset is for GROUPS of controls"
    }
  ],
  "relatedComponents": [
    "Radio",
    "Checkbox",
    "FormField",
    "Label"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.8.0",
  "sourceDir": "fieldset",
  "exportName": "Fieldset"
}
